// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List CIDR allocations
	// (GET /v1/cidr/allocations)
	ListCIDRAllocations(ctx context.Context, request ListCIDRAllocationsRequestObject) (ListCIDRAllocationsResponseObject, error)
	// Get async job status
	// (GET /v1/jobs/{jobId})
	GetJob(ctx context.Context, request GetJobRequestObject) (GetJobResponseObject, error)
	// Provision a tenant private network
	// (POST /v1/networks)
	ProvisionNetwork(ctx context.Context, request ProvisionNetworkRequestObject) (ProvisionNetworkResponseObject, error)
	// Deprovision a network
	// (DELETE /v1/networks/{networkId})
	DeprovisionNetwork(ctx context.Context, request DeprovisionNetworkRequestObject) (DeprovisionNetworkResponseObject, error)
	// Get network provisioning status
	// (GET /v1/networks/{networkId})
	GetNetworkProvisioningStatus(ctx context.Context, request GetNetworkProvisioningStatusRequestObject) (GetNetworkProvisioningStatusResponseObject, error)
	// Remove the internet gateway
	// (DELETE /v1/networks/{networkId}/gateway)
	RemoveGateway(ctx context.Context, request RemoveGatewayRequestObject) (RemoveGatewayResponseObject, error)
	// Get internet gateway status
	// (GET /v1/networks/{networkId}/gateway)
	GetGatewayStatus(ctx context.Context, request GetGatewayStatusRequestObject) (GetGatewayStatusResponseObject, error)
	// Provision an internet gateway for a network
	// (POST /v1/networks/{networkId}/gateway)
	ProvisionGateway(ctx context.Context, request ProvisionGatewayRequestObject) (ProvisionGatewayResponseObject, error)
	// List jobs for a network
	// (GET /v1/networks/{networkId}/jobs)
	ListNetworkJobs(ctx context.Context, request ListNetworkJobsRequestObject) (ListNetworkJobsResponseObject, error)
	// List subnets in a network
	// (GET /v1/networks/{networkId}/subnets)
	ListSubnets(ctx context.Context, request ListSubnetsRequestObject) (ListSubnetsResponseObject, error)
	// Create a subnet in a network
	// (POST /v1/networks/{networkId}/subnets)
	CreateSubnet(ctx context.Context, request CreateSubnetRequestObject) (CreateSubnetResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

